function bracketDots(address: string): string {
  let out = "";
  for (const ch of address) out += ch === "." ? "[.]" : ch;
  return out;
}

solutions.py:
class Solution:
    def bracketDots(self, address: str) -> str:
        return "".join("[.]" if ch == "." else ch for ch in address)

